1	/**
2	 * Scoped per testing.md: this component's own contract (given props, does it render the right
3	 * branch and wire the right handler) — not ZimmProductName/ZimmProductPrice/ZimmSizeChipGroup's
4	 * own internal logic, which is already proven in their own index.test.tsx files. All three are
5	 * lightweight, side-effect-free presentational components, so composing them directly for real
6	 * (rather than mocking them out) still costs nothing and gives genuine integration confidence
7	 * that this component passes them the right props — same precedent as
8	 * zimmProductCardMedia/index.test.tsx composing the real ZimmSlideIndicator.
9	 *
10	 * Only `useMultiStyleConfig` is mocked (this component's own 11 parts). `useStyleConfig` (used
11	 * internally by ZimmProductName) is left real/unmocked — it resolves an unregistered recipe key
12	 * to `{}` gracefully with no ChakraProvider present, exactly as ZimmProductName's own
13	 * (unmocked) index.test.tsx already relies on; only the multi-part hook needs a mock here (see
14	 * zimmSizeChipGroup/index.test.tsx's identical comment on this same distinction).
15	 */
16	import React from 'react';
17	import { describe, test, expect, vi } from 'vitest';
18	import { render, screen, within, fireEvent } from '@testing-library/react';
19	import userEvent from '@testing-library/user-event';
20	import { IntlProvider } from 'react-intl';
21	import { MemoryRouter } from 'react-router-dom';
22	import { ZimmProductCardContent } from './index';
23	import type { ZimmProductCardContentProps } from './index';
24	import { ZimmProductCardContent as ZimmProductCardContentRecipe } from './zimmProductCardContent.css';
25	import type { ZimmSizeChipValue } from '../zimmSizeChipGroup';
26	
27	// Flat parts object covering only this component's own recipe. ZimmProductPrice/
28	// ZimmSizeChipGroup/ZimmSizeChip's own `styles.X` reads resolve to `undefined` under this same
29	// mock, which is a legal, harmless `__css` value — same precedent
30	// zimmSizeChipGroup/index.test.tsx documents for ZimmSizeChip's own unresolved `styles.chip`.
31	vi.mock('@chakra-ui/react', async (importOriginal) => {
32	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
33	  return {
34	    ...actual,
35	    useMultiStyleConfig: () => ({
36	      root: {},
37	      nameRow: {},
38	      nameLink: {},
39	      bagWrapper: {},
40	      bagButton: {},
41	      attributesRow: {},
42	      colourText: {},
43	      sizeText: {},
44	      priceWrapper: {},
45	      sizeChipWrapper: {},
46	      notifyMeButton: {},
47	    }),
48	  };
49	});
50	
51	// ZimmIcon: known Vitest SVG side-effect issue (.claude/rules/testing.md). The bag button's
52	// accessible name comes from the button's own aria-label, not the icon, so the icon can safely
53	// resolve to null rather than needing to forward any props. Mocked at the same relative
54	// specifier this component imports it from.
55	vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
56	
57	const wrap = (ui: React.ReactElement) =>
58	  render(
59	    <MemoryRouter>
60	      <IntlProvider locale="en" defaultLocale="en">
61	        {ui}
62	      </IntlProvider>
63	    </MemoryRouter>,
64	  );
65	
66	const BASE_PROPS: ZimmProductCardContentProps = {
67	  name: 'Natura Long Sleeve Linen Mini Dress',
68	  headingLevel: 'h3',
69	  href: '/product/123',
70	  showAttributes: false,
71	  showBag: false,
72	  showSizeChips: false,
73	  showNotifyMe: false,
74	};
75	
76	const SIZES: ZimmSizeChipValue[] = [
77	  { value: 'xs', label: 'XS' },
78	  { value: 's', label: 'S' },
79	];
80	
81	describe('ZimmProductCardContent — name renders as a link to the PDP', () => {
82	  test('renders the product name as a heading, linked to href, at the given heading level', () => {
83	    wrap(<ZimmProductCardContent {...BASE_PROPS} name="Natura Dress" headingLevel="h2" href="/product/123" />);
84	    const link = screen.getByRole('link', { name: 'Natura Dress' });
85	    expect(link).toHaveAttribute('href', '/product/123');
86	    expect(screen.getByRole('heading', { level: 2, name: 'Natura Dress' })).toBeInTheDocument();
87	  });
88	
89	  test('renders a different heading level when headingLevel changes', () => {
90	    wrap(<ZimmProductCardContent {...BASE_PROPS} headingLevel="h2" />);
91	    expect(screen.getByRole('heading', { level: 2 })).toBeInTheDocument();
92	    expect(screen.queryByRole('heading', { level: 3 })).not.toBeInTheDocument();
93	  });
94	});
95	
96	describe('ZimmProductCardContent — bag control', () => {
97	  test('is absent when showBag is false', () => {
98	    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag={false} />);
99	    expect(screen.queryByRole('button', { name: 'Add to bag' })).not.toBeInTheDocument();
100	  });
101	
102	  test('renders a labelled native button when showBag is true', () => {
103	    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag />);
104	    const button = screen.getByRole('button', { name: 'Add to bag' });
105	    expect(button.tagName).toBe('BUTTON');
106	    expect(button).not.toBeDisabled();
107	  });
108	
109	  test('calls onAddToBag when clicked while available', async () => {
110	    const onAddToBag = vi.fn();
111	    const user = userEvent.setup();
112	    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag onAddToBag={onAddToBag} />);
113	    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
114	    expect(onAddToBag).toHaveBeenCalledTimes(1);
115	  });
116	
117	  test('is disabled via the native disabled attribute when isUnavailable is true', () => {
118	    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag isUnavailable />);
119	    expect(screen.getByRole('button', { name: 'Add to bag' })).toBeDisabled();
120	  });
121	
122	  test('never calls onAddToBag when isUnavailable, even when a click is dispatched directly', () => {
123	    const onAddToBag = vi.fn();
124	    wrap(<ZimmProductCardContent {...BASE_PROPS} showBag isUnavailable onAddToBag={onAddToBag} />);
125	    const button = screen.getByRole('button', { name: 'Add to bag' });
126	    // A native `disabled` button never dispatches a click at all — this is the browser's own
127	    // enforcement, not this component's guard clause, which is exactly what makes it reliable.
128	    fireEvent.click(button);
129	    expect(onAddToBag).not.toHaveBeenCalled();
130	  });
131	});
132	
133	describe('ZimmProductCardContent — attributes row (wishlist only)', () => {
134	  test('renders colour and size as visible text when showAttributes is true', () => {
135	    wrap(<ZimmProductCardContent {...BASE_PROPS} showAttributes colour="Ivory" size="M" />);
136	    const row = screen.getByTestId('card-content-attributes');
137	    expect(within(row).getByText('Ivory')).toBeInTheDocument();
138	    expect(within(row).getByText('M')).toBeInTheDocument();
139	  });
140	
141	  test('is absent from the DOM entirely (not merely hidden) when showAttributes is false', () => {
142	    wrap(<ZimmProductCardContent {...BASE_PROPS} showAttributes={false} colour="Ivory" size="M" />);
143	    // queryBy, not a display/visibility check — the row must not exist at all, per the
144	    // component contract's explicit "absent from the DOM entirely" requirement.
145	    expect(screen.queryByTestId('card-content-attributes')).not.toBeInTheDocument();
146	    expect(screen.queryByText('Ivory')).not.toBeInTheDocument();
147	  });
148	});
149	
150	describe('ZimmProductCardContent — price', () => {
151	  test('the price wrapper is present in the DOM by default (no other variation flags set)', () => {
152	    wrap(<ZimmProductCardContent {...BASE_PROPS} currentPrice="$595.00" />);
153	    expect(document.querySelector('[data-card-slot="price"]')).toBeInTheDocument();
154	  });
155	
156	  test('the price wrapper is still present when every other slot is also active — not mutually exclusive', () => {
157	    wrap(
158	      <ZimmProductCardContent
159	        {...BASE_PROPS}
160	        currentPrice="$595.00"
161	        showAttributes
162	        colour="Ivory"
163	        size="M"
164	        showBag
165	        showSizeChips
166	        sizeChipValues={SIZES}
167	      />,
168	    );
169	    expect(document.querySelector('[data-card-slot="price"]')).toBeInTheDocument();
170	    expect(screen.getByTestId('card-content-attributes')).toBeInTheDocument();
171	  });
172	
173	  test('passes isLive={false} through to ZimmProductPrice — no aria-live/aria-atomic present', () => {
174	    wrap(<ZimmProductCardContent {...BASE_PROPS} currentPrice="$595.00" />);
175	    const price = screen.getByTestId('product-price');
176	    expect(price).not.toHaveAttribute('aria-live');
177	    expect(price).not.toHaveAttribute('aria-atomic');
178	  });
179	
180	  test('passes currentPrice/originalPrice straight through (Was/Now sale treatment)', () => {
181	    wrap(<ZimmProductCardContent {...BASE_PROPS} currentPrice="$595.00" originalPrice="$795.00" />);
182	    expect(screen.getByTestId('product-was-price')).toHaveTextContent('Was $795.00');
183	    expect(screen.getByTestId('product-now-price')).toHaveTextContent('Now $595.00');
184	  });
185	
186	  test('passes isPriceLoading through as ZimmProductPrice’s own isLoading', () => {
187	    // ZimmProductPrice's loading branch is checked before its own `!currentPrice` null-check, so
188	    // seeing the price node render with no currentPrice at all proves isPriceLoading genuinely
189	    // reached isLoading, rather than this assertion coincidentally passing some other way.
190	    wrap(<ZimmProductCardContent {...BASE_PROPS} isPriceLoading />);
191	    expect(screen.getByTestId('product-price')).toBeInTheDocument();
192	  });
193	
194	  test('renders nothing from ZimmProductPrice when there is no price and no loading state', () => {
195	    wrap(<ZimmProductCardContent {...BASE_PROPS} />);
196	    expect(screen.queryByTestId('product-price')).not.toBeInTheDocument();
197	  });
198	});
199	
200	describe('ZimmProductCardContent — size-chip slot (PLP only)', () => {
201	  test('is absent entirely when showSizeChips is false, even when values are supplied', () => {
202	    wrap(<ZimmProductCardContent {...BASE_PROPS} showSizeChips={false} sizeChipValues={SIZES} />);
203	    expect(document.querySelector('[data-card-slot="sizeChips"]')).not.toBeInTheDocument();
204	    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
205	  });
206	
207	  test('renders the composed ZimmSizeChipGroup when showSizeChips is true', () => {
208	    wrap(<ZimmProductCardContent {...BASE_PROPS} showSizeChips sizeChipValues={SIZES} selectedSizeChipValue="s" />);
209	    expect(document.querySelector('[data-card-slot="sizeChips"]')).toBeInTheDocument();
210	    expect(screen.getByRole('radio', { name: 'S' })).toHaveAttribute('aria-checked', 'true');
211	  });
212	
213	  test('forwards onSizeChipSelect straight through to the composed group', async () => {
214	    const onSizeChipSelect = vi.fn();
215	    const user = userEvent.setup();
216	    wrap(
217	      <ZimmProductCardContent
218	        {...BASE_PROPS}
219	        showSizeChips
220	        sizeChipValues={SIZES}
221	        onSizeChipSelect={onSizeChipSelect}
222	      />,
223	    );
224	    await user.click(screen.getByRole('radio', { name: 'XS' }));
225	    expect(onSizeChipSelect).toHaveBeenCalledWith('xs');
226	  });
227	
228	  test('defaults to an empty size list without crashing when sizeChipValues is omitted', () => {
229	    wrap(<ZimmProductCardContent {...BASE_PROPS} showSizeChips />);
230	    expect(document.querySelector('[data-card-slot="sizeChips"]')).toBeInTheDocument();
231	    // ZimmSizeChipGroup itself renders null for an empty values array.
232	    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
233	  });
234	});
235	
236	describe('ZimmProductCardContent — notify-me control', () => {
237	  test('is absent when showNotifyMe is true but onNotifyMe is not supplied', () => {
238	    wrap(<ZimmProductCardContent {...BASE_PROPS} showNotifyMe />);
239	    expect(screen.queryByRole('button', { name: 'Notify me' })).not.toBeInTheDocument();
240	  });
241	
242	  test('is absent when onNotifyMe is supplied but showNotifyMe is false', () => {
243	    wrap(<ZimmProductCardContent {...BASE_PROPS} showNotifyMe={false} onNotifyMe={vi.fn()} />);
244	    expect(screen.queryByRole('button', { name: 'Notify me' })).not.toBeInTheDocument();
245	  });
246	
247	  test('renders a real, labelled button and calls onNotifyMe on click when both conditions hold', async () => {
248	    const onNotifyMe = vi.fn();
249	    const user = userEvent.setup();
250	    wrap(<ZimmProductCardContent {...BASE_PROPS} showNotifyMe onNotifyMe={onNotifyMe} />);
251	    const button = screen.getByRole('button', { name: 'Notify me' });
252	    expect(button.tagName).toBe('BUTTON');
253	    await user.click(button);
254	    expect(onNotifyMe).toHaveBeenCalledTimes(1);
255	  });
256	});
257	
258	describe('ZimmProductCardContent — data-card-slot selector contract for the organism (Step 6)', () => {
259	  test('stamps content/price/sizeChips when all optional slots are active', () => {
260	    wrap(<ZimmProductCardContent {...BASE_PROPS} currentPrice="$100.00" showSizeChips sizeChipValues={SIZES} />);
261	    expect(document.querySelector('[data-card-slot="content"]')).toBeInTheDocument();
262	    expect(document.querySelector('[data-card-slot="price"]')).toBeInTheDocument();
263	    expect(document.querySelector('[data-card-slot="sizeChips"]')).toBeInTheDocument();
264	  });
265	});
266	
267	/**
268	 * Real-recipe assertions — bypasses the useMultiStyleConfig mock entirely, same technique as
269	 * zimmProductCardMedia/index.test.tsx's own "Fix 1" block. The component-level tests above all
270	 * render through the flat mock at the top of this file, which can't see whether the real recipe
271	 * ever regresses the focus ring or accidentally hides the size-chip slot — both are exactly the
272	 * kind of CSS-only, "would survive a refactor invisibly if broken" behaviour testing.md calls
273	 * out, and the focus-ring gap specifically has already been caught twice in this build (Step 2,
274	 * Step 4) after being missed by mocked component tests alone.
275	 */
276	describe('ZimmProductCardContent — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
277	  const EXPECTED_FOCUS_VISIBLE = {
278	    outline: 'var(--zimm-focus-ring)',
279	    outlineOffset: 'var(--zimm-focus-ring-offset-default)',
280	  };
281	
282	  test('nameLink, bagButton and notifyMeButton all carry the standard keyboard focus-visible outline', () => {
283	    const style = ZimmProductCardContentRecipe.baseStyle({});
284	    expect((style.nameLink as Record<string, unknown>)._focusVisible).toEqual(EXPECTED_FOCUS_VISIBLE);
285	    expect((style.bagButton as Record<string, unknown>)._focusVisible).toEqual(EXPECTED_FOCUS_VISIBLE);
286	    expect((style.notifyMeButton as Record<string, unknown>)._focusVisible).toEqual(EXPECTED_FOCUS_VISIBLE);
287	  });
288	
289	  test('sizeChipWrapper never sets display:none — visibility belongs to the Step 6 organism, not this recipe', () => {
290	    const style = ZimmProductCardContentRecipe.baseStyle({});
291	    expect((style.sizeChipWrapper as Record<string, unknown>).display).not.toBe('none');
292	  });
293	
294	  test('bagButton cursor and colour resolve per the disabled style prop', () => {
295	    const enabled = ZimmProductCardContentRecipe.baseStyle({ disabled: false });
296	    const disabled = ZimmProductCardContentRecipe.baseStyle({ disabled: true });
297	
298	    expect(enabled.bagButton.cursor).toBe('pointer');
299	    expect(disabled.bagButton.cursor).toBe('not-allowed');
300	    expect(enabled.bagButton.color).toBe('var(--zimm-color-text-default)');
301	    expect(disabled.bagButton.color).toBe('var(--zimm-color-text-muted)');
302	  });
303	});
