// Verification-only script (not part of the repo). Renders the real Futura Round Medium font
// at the exact `caption` textStyle metrics (12px / 500 / 18px line-height / 0 letter-spacing)
// used by zimmProductCardContent's attributesRow, and measures whether a 2px flex `gap` between
// two spans ("Ivory," + "M") reads as a natural "Ivory, M" phrase or a cramped "Ivory,M".
//
// Two independent measurement techniques:
//   1. Canvas TextMetrics ink bounds (actualBoundingBoxLeft/Right) — the "advance box" of a
//      glyph (what CSS gap/flex measures between) includes side-bearing whitespace baked into
//      the font beyond the visible ink. This computes the REAL visual gap: comma's own trailing
//      ink-to-advance-edge whitespace + the 2px CSS gap + M's own leading ink-to-advance-edge
//      whitespace — vs. the font's natural space-character advance width as the baseline for
//      "what a normal word-space looks like."
//   2. Real DOM flex layout via getBoundingClientRect, cross-checked against (1), plus a
//      full-page screenshot for visual sanity-check.
import { chromium } from 'playwright';
import fs from 'node:fs';
import path from 'node:path';

const fontB64 = fs
  .readFileSync(
    '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/072a647c-adc5-46b1-8bb0-e024b43fd490/scratchpad/futura-medium-b64-oneline.txt',
    'utf8',
  )
  .trim();

const html = `<!doctype html>
<html><head><meta charset="utf-8">
<style>
  @font-face {
    font-family: 'Futura Round Test';
    src: url(data:font/woff2;base64,${fontB64}) format('woff2');
    font-weight: 500;
    font-style: normal;
    font-display: block;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { background: #fff; padding: 40px; }
  .caption {
    font-family: 'Futura Round Test', sans-serif;
    font-size: 0.75rem;      /* fontSizes['3xs'] = 12px, matches caption textStyle */
    font-weight: 500;         /* fontWeights.medium */
    line-height: 1.125rem;    /* lineHeights['2xs'] = 18px */
    letter-spacing: 0;        /* letterSpacings.sm */
    color: #666;
  }
  .row { display: flex; align-items: center; margin-bottom: 24px; outline: 1px dashed #ccc; width: max-content; }
  .row span { margin: 0; }
  .gap2 { gap: 2px; }
  .gap4 { gap: 4px; }
  .gap0 { gap: 0px; }
  .label { font-family: monospace; font-size: 11px; color: #f00; margin-bottom: 2px; }
</style>
</head>
<body>
  <div class="label">A: two spans, "Ivory," + gap:2px + "M" (proposed Fix 2, no baked-in space)</div>
  <div class="row gap2 caption" id="rowA"><span id="a1">Ivory,</span><span id="a2">M</span></div>

  <div class="label">B: two spans, "Ivory, " (baked-in trailing space) + gap:2px + "M"</div>
  <div class="row gap2 caption" id="rowB"><span id="b1">Ivory, </span><span id="b2">M</span></div>

  <div class="label">C: single span, natural inline text "Ivory, M" (ground truth reference)</div>
  <div class="row caption" id="rowC"><span id="c1">Ivory, M</span></div>

  <div class="label">D: two spans, "Ivory," + gap:0 + "M" (cramped baseline, for contrast)</div>
  <div class="row gap0 caption" id="rowD"><span id="d1">Ivory,</span><span id="d2">M</span></div>

  <div class="label">E: real Figma copy — "Lilac Sand," + gap:2px + "One size"</div>
  <div class="row gap2 caption" id="rowE"><span id="e1">Lilac Sand,</span><span id="e2">One size</span></div>
</body></html>`;

const run = async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ deviceScaleFactor: 4 }); // supersample for pixel accuracy
  await page.setContent(html);
  await page.evaluate(async () => {
    await document.fonts.load('500 12px "Futura Round Test"');
    await document.fonts.ready;
  });

  // --- Technique 1: canvas ink-bound metrics ---
  const canvasMetrics = await page.evaluate(() => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    ctx.font = '500 12px "Futura Round Test"';
    ctx.textBaseline = 'alphabetic';

    const measure = (text) => {
      const m = ctx.measureText(text);
      return {
        text,
        advanceWidth: m.width,
        actualLeft: m.actualBoundingBoxLeft, // distance from x=0 to leftmost ink (positive = ink starts right of x=0)
        actualRight: m.actualBoundingBoxRight, // distance from x=0 to rightmost ink
      };
    };

    const comma = measure('Ivory,');
    const emM = measure('M');
    const space = measure(' ');
    const lilacComma = measure('Lilac Sand,');
    const oneSize = measure('One size');

    // Trailing whitespace baked into "Ivory,"'s own advance box, beyond its visible ink:
    const trailingAfterComma = comma.advanceWidth - comma.actualRight;
    // Leading whitespace baked into "M"'s own advance box, before its visible ink starts
    // (measured by drawing at x=0, so actualLeft IS the left bearing directly):
    const leadingBeforeM = emM.actualLeft;

    const trailingAfterLilacComma = lilacComma.advanceWidth - lilacComma.actualRight;
    const oneSizeMeasure = measure('One size');
    const leadingBeforeOneSize = oneSizeMeasure.actualLeft;

    return {
      comma,
      emM,
      space,
      trailingAfterComma,
      leadingBeforeM,
